  const isProcessed = await redis.set(`processed:${event.idempotencyKey}`, "1", "NX", "EX", 86400);
  if (!isProcessed) {
    logger.warn(`Evento duplicado detectado: ${event.idempotencyKey}. Ignorando.`);
    return;
  }
  await paymentGateway.charge(event.amount);
}

